#include <sstream>
#define main old_main
#include "search.cpp"
#undef main
using A9=array<int,512>;struct Move{P p,bridge;int k,h,L,M,seq,lp,up,oldLow,goal,budget,nodes,best=0;A9 occ{},ns{};long long calls=0,win=0,caps=0,raw=0;set<pair<P,P>> fresh;ofstream o,w;mt19937 rng{1121};array<int,8> dirs{0,1,2,3,4,5,6,7};
 Move(string tag):o(tag+".paths"),w(tag+".forests"){}
 void mark9(int v,int t){occ[v]+=t;for(int d=0;d<9;d++)ns[v^1<<d]+=t;}
 void done(){P q(p.begin(),p.begin()+k);q.insert(q.end(),bridge.begin(),bridge.end());q.insert(q.end(),p.begin()+h+1,p.end());if((int)q.size()!=goal+1)abort();P a,b;bool which=false;for(int j=0;j<(int)q.size();j++){if(j&&q[j]>=256&&q[j-1]<256)which=true;if(q[j]<256)(which?b:a).push_back(q[j]);}if(b.size()>a.size())swap(a,b);if(a.size()-1<92||a.size()-1>93||b.size()-1<3||b.size()-1>8)abort();
 raw++;P ka=a,kb=b;sort(ka.begin(),ka.end());sort(kb.begin(),kb.end());bool novel=fresh.insert({ka,kb}).second;if(novel||goal>best){for(int j=0;j<(int)q.size();j++)for(int i=0;i<j;i++)if(q[i]==q[j]||near(q[i],q[j])!=(i+1==j))abort();best=max(goal,best);o<<goal<<" "<<seq<<" 1 "<<a.size()-1<<" "<<b.size()-1;for(int v:q)o<<" "<<v;o<<endl;if(novel){w<<"1 0 0 0 "<<a.size();for(int v:a)w<<" "<<v;w<<" "<<b.size();for(int v:b)w<<" "<<v;w<<endl;}if(best>=192)cout<<"FOUND "<<best<<endl;}}
 void dfs(int l,int u,bool high){if(best>=192||++nodes>budget)return;calls++;int v=bridge.back(),t=p[h];if(popcount((unsigned)((v^t)&255))>l+u)return;if(high&&!u){if(v==t)done();return;}if(!high&&!l){int x=v^256;if(occ[x]||ns[x]!=1||x==t)return;mark9(x,1);bridge.push_back(x);dfs(0,u,true);bridge.pop_back();mark9(x,-1);return;}
 for(int d:dirs){int x=v^1<<d;bool last=high&&u==1;if(last){if(x!=t||ns[x]!=(1+(h+1<(int)p.size())))continue;bridge.push_back(x);dfs(0,0,true);bridge.pop_back();continue;}if(occ[x]||ns[x]!=1||x==t)continue;mark9(x,1);bridge.push_back(x);dfs(l-int(!high),u-int(high),high);bridge.pop_back();mark9(x,-1);if(nodes>budget||best>=192)return;}}
 void run(){occ={};ns={};for(int i=0;i<=k;i++)mark9(p[i],1);for(int i=h+1;i<(int)p.size();i++)mark9(p[i],1);nodes=0;bridge={p[k]};win++;dfs(lp,up,false);caps+=nodes>budget;}
};
int main(int argc,char**argv){if(argc!=7)return 1;Move m(argv[6]);m.budget=atoi(argv[4]);int limit=atoi(argv[3]),step=atoi(argv[5]);ifstream input(argv[1]);string line;while(getline(input,line)){istringstream is(line);int n,id,source,major,minor;is>>n>>id>>source>>major>>minor;int x;P old;while(is>>x)old.push_back(x);for(int goaloff=0;goaloff<(string(argv[2])=="discover"?5:1);goaloff++){m.goal=string(argv[2])=="discover"?188-goaloff*2:atoi(argv[2]);for(int rev=0;rev<2;rev++){m.p=old;if(rev)reverse(m.p.begin(),m.p.end());for(int i=0;i+1<(int)old.size();i++)if(m.p[i]<256&&m.p[i+1]>=256){int a=i,z=i+1;while(a>0&&m.p[a-1]<256)a--;while(z+1<(int)old.size()&&m.p[z+1]>=256)z++;int oldL=i-a;for(int ll=1;ll<=limit&&ll<=i-a;ll+=step)for(int uu=1;uu<=limit&&uu<=z-i-1;uu+=step)for(int L=(oldL>=90?92:3);L<=(oldL>=90?93:8);L++){m.seq=id;m.k=i-ll;m.h=i+1+uu;m.lp=ll+L-oldL;m.up=uu+m.goal-n-(L-oldL);if(m.lp<0||m.up<1)continue;shuffle(m.dirs.begin(),m.dirs.end(),m.rng);m.run();if(m.best>=192)goto end;}}}}}end:cout<<"windows "<<m.win<<" calls "<<m.calls<<" caps "<<m.caps<<" real "<<m.raw<<" lower_geometries "<<m.fresh.size()<<" best "<<m.best<<endl;}
